export function exportActive(d:Draft,source:ReviewSource){return {schemaVersion:2,sourceRevision:source.revision,entities:d.entities.filter(e=>!e.archived).map(e=>({...activeEntity(d,e,source),issues:issues(d,e,source),readiness:readiness(d,e,source),validForAnalysis:!issues(d,e,source).some(i=>i.hard)})),tasks:d.tasks.map(t=>({...t,closed:!!t.closedHash&&t.closedHash===taskHash(d,t)}))};}

export function planningReadiness(d:Draft,e:Entity,source:ReviewSource,authority:Authority[]):Readiness[]{
 const v=values(e,'APPROVE-01'),plans=list(v,'planning');const missing=(path:string[],message:string):Issue=>({entityId:e.id,group:'APPROVE-01',path,message,hard:false});
 if(!plans.length)return [{dimension:'Demand and stock coverage',status:'Partial — named gaps',gaps:[missing(['planning'],'Choose the products/process, variants and planning period first.')],scope:'No planning scope selected',estimates:0}];
 return plans.map(plan=>{const gaps=[...fieldIssues(d,e,groups.find(g=>g.id==='APPROVE-01')!).filter(i=>i.path[0]!=='planning'||i.path[1]===plan.id),...confirmationGaps(d,e,['APPROVE-01'],source)];let estimates=0;const p=entity(d,plan.process);if(!dateValid(plan.start)||!dateValid(plan.end)||String(plan.end)<String(plan.start)||String(plan.end)>=today())gaps.push(missing(['planning',String(plan.id)],'Use one completed, consistent planning period.'));
 for(const [value,complete,label] of [[plan.salesChecked,'Complete current records checked','demand'],[plan.stockChecked,'Complete usable stock, movements and losses checked','usable stock and losses']]){if(value==='Estimate')estimates++;else if(value!==complete)gaps.push(missing(['planning',String(plan.id)],'Complete '+label+' coverage.'));}
 const collect=(rs:Readiness[])=>{for(const r of rs){estimates+=r.estimates;if(!['Ready with stated scope','Usable estimate','Not applicable'].includes(r.status))gaps.push(...r.gaps.length?r.gaps:[missing(['planning',String(plan.id)],r.dimension+' remains outside the usable scope.')]);}};
 for(const ref of list(plan,'dishes')){const dish=entity(d,ref.dish);if(dish){if(values(dish,'MENU-01').practice!=='Current practice'||!['Served now','Rotating recipe'].includes(str(values(dish,'MENU-01'),'status')))gaps.push(missing(['planning',String(plan.id),'dishes'],'Select a current served dish variant.'));if(values(dish,'MENU-01').startKnown!=='Exact date known'||String(values(dish,'MENU-01').effective)>String(plan.start))gaps.push(missing(['planning',String(plan.id),'dishes'],'Confirm the variant version that applied throughout this period.'));}if(dish)collect(readiness(d,dish,source,authority).filter(r=>['Direct dish composition','Base ingredient breakdown','Portion consumption'].includes(r.dimension)));const mappings=list(v,'sales').filter(x=>x.dish===ref.dish&&x.start===plan.start&&x.end===plan.end);if(mappings.some(mapping=>!dateValid(mapping.effective)||String(mapping.effective)>String(plan.start)))gaps.push(missing(['sales'],'The POS mapping must apply throughout the selected period.'));if(mappings.length!==1)gaps.push(missing(['sales'],'Provide one exact POS mapping, modifier coverage and availability for each scoped variant and period.'));}
 if(p){if(values(p,'PROC-01').startKnown!=='Exact date known'||String(values(p,'PROC-01').effective)>String(plan.start))gaps.push(missing(['planning',String(plan.id)],'Confirm the process version that applied throughout this period.'));gaps.push(...issues(d,p,source),...confirmationGaps(d,p,['PROC-01','PROC-02','PROC-03','PROC-04','PROC-05'],source));if(outOfScope(d,p,source))gaps.push(missing(['planning',String(plan.id)],'Shared production is outside this review; its total contribution remains unavailable.'));const runs=d.entities.filter(x=>!x.archived&&x.kind==='run'&&processFor(d,x)?.id===p.id);const usable=runs.filter(r=>readiness(d,r,source,authority).some(x=>x.dimension==='Labour per recorded run'&&['Ready with stated scope','Usable estimate'].includes(x.status))&&!issues(d,r,source).some(i=>['RUN-08','RUN-10'].includes(i.group))&&!confirmationGaps(d,r,['RUN-08','RUN-10'],source).length);if(!usable.length)gaps.push(missing(['planning',String(plan.id)],'A scoped run needs confirmed labour, lead time and tested capacity.'));else{const assessments=usable.map(r=>readiness(d,r,source,authority).filter(x=>x.dimension==='Labour per recorded run'));assessments.sort((a,b)=>a.reduce((n,x)=>n+x.estimates,0)-b.reduce((n,x)=>n+x.estimates,0));collect(assessments[0]);if(usable.some(r=>JSON.stringify([values(r,'RUN-08'),values(r,'RUN-10')]).toLowerCase().includes('estimate')))estimates++;}
 for(const o of list(values(p,'PROC-03'),'outputs').filter(x=>x.type==='Usable product')){if(!list(v,'stock').some(s=>s.item===o.item&&s.phase===o.phase&&s.start===plan.start&&s.end===plan.end))gaps.push(missing(['stock'],'Add matching usable stock, movement and loss records for '+(entity(d,o.item)?.name??'output')+'.'));if(!list(plan,'states').some(s=>values(entity(d,s.storage),'STORE-01').item===o.item&&values(entity(d,s.storage),'STORE-01').phase===o.phase&&(!o.source||values(entity(d,s.storage),'STORE-01').source===o.source)))gaps.push(missing(['planning',String(plan.id),'states'],'Include every actual output storage state.'));}}
 if(plan.statesComplete!=='All actual states included')gaps.push(missing(['planning',String(plan.id),'statesComplete'],'Storage-state coverage is incomplete.'));for(const st of list(plan,'states')){const store=entity(d,st.storage);if(store)collect(readiness(d,store,source,authority));}
 return {dimension:'Demand and stock coverage',status:gaps.length?'Partial — named gaps':estimates?'Usable estimate':'Ready with stated scope',gaps,scope:(p?.name??'Planning scope')+' · '+String(plan.start??'?')+' to '+String(plan.end??'?')+' · Readiness of planning inputs, not an optimal batch',estimates};});
}

export function comparableRuns(d:Draft,a:Entity,b:Entity){if(a.kind!=='run'||b.kind!=='run'||a.id===b.id)return false;const pa=processFor(d,a),pb=processFor(d,b),av=values(a,'RUN-01'),bv=values(b,'RUN-01'),c=values(a,'RUN-09');const types=[av.size,bv.size];if(new Set(types).size!==2||!types.every(t=>t==='Usual full batch'||t==='Small top-up'))return false;const explicit=c.comparable==='Differences documented and comparable'&&!!str(c,'comparisonEvidence').trim();if(pa?.id!==pb?.id&&!(explicit&&(values(pa,'PROC-01').alternative===pb?.id||values(pb,'PROC-01').alternative===pa?.id)))return false;
 const outputs=(e:Entity,p:Entity|undefined)=>list(values(e,'RUN-03'),'outputs').map(q=>{const o=list(values(p,'PROC-03'),'outputs').find(x=>x.id===q.output);return JSON.stringify([o?.item,o?.phase,o?.source,baseUnit(str(q,'unit'))[0],q.coverage]);}).sort();if(!same(outputs(a,pa),outputs(b,pb)))return false;
 const coverage=(e:Entity)=>steps.map(k=>list(values(e,'RUN-06'),'coverage')[0]?.[k]);return explicit||c.comparable==='Same method and conditions'&&av.conditions===bv.conditions&&same(coverage(a),coverage(b));}

export function interviewGaps(d:Draft,source:ReviewSource):Issue[]{return d.entities.filter(e=>!e.archived&&e.kind!=='manager').flatMap(e=>issues(d,e,source)).filter(gap=>!d.tasks.some(t=>t.owner.trim()&&dateValid(t.due)&&t.method.trim()&&t.reason.trim()&&t.targets.some(t=>t.entityId===gap.entityId&&t.group===gap.group&&(t.path.length===0||t.path.every((p,i)=>gap.path[i]===p)))));}
